package com.oveduumnakal.goatindicators;

import java.util.Arrays;
import java.util.Collections;
import java.util.HashSet;
import java.util.Set;

/**
 * Every game-side identifier and name fragment the plugin recognises, in one place.
 *
 * <p>The goat pit is not present in the {@code net.runelite.api.gameval} constants shipped with the
 * RuneLite API, so nothing here can be imported from there. Detection was therefore designed to work
 * <em>structurally</em> — matching the object's name and reading the count from the varbit the object
 * composition itself declares ({@link net.runelite.api.ObjectComposition#getVarbitId()}) — as a path
 * that needs no known id. In practice a developer-mode session pinned the confirmed ids and varbits
 * below, so those are what the plugin uses; the structural path is only the fallback, and a partial one
 * — it restores the footprint outline but not the count/spikes state (see {@link GoatPitTracker}).
 *
 * <p>{@link #PIT_OBJECT_IDS} is an optional allowlist. Leave it empty to fall back to name matching; fill
 * it in from a developer-mode session (see {@code docs/discovery.md}) to pin detection to exact ids.
 */
final class GoatIds
{
	/**
	 * Smallest and largest goat pit capacity. The pit's capacity is not fixed: it scales with the
	 * player's Hunter level, from {@code 16} at level 60 up to {@code 24} at level 93+. See
	 * {@link #capacityForHunterLevel(int)}.
	 */
	static final int MIN_CAPACITY = 16;
	static final int MAX_CAPACITY = 24;

	/**
	 * How many goats a pit holds when full at the given Hunter level. Capacity rises in steps with the
	 * level, per the OSRS Wiki (<a href="https://oldschool.runescape.wiki/w/Goat_pit">Goat pit</a>):
	 *
	 * <pre>
	 *   Hunter 60-68 -&gt; 16    Hunter 85-92 -&gt; 22
	 *   Hunter 69-76 -&gt; 18    Hunter 93+   -&gt; 24
	 *   Hunter 77-84 -&gt; 20
	 * </pre>
	 *
	 * The step up to {@code 18} lands at level 69, not 70 (confirmed in-game by a player reaching 69).
	 * Levels below 60 cannot use the pit, so they also return {@link #MIN_CAPACITY}.
	 *
	 * @param hunterLevel the player's Hunter level (real, unboosted)
	 * @return the pit capacity for that level, always within {@link #MIN_CAPACITY}..{@link #MAX_CAPACITY}
	 */
	static int capacityForHunterLevel(int hunterLevel)
	{
		if (hunterLevel >= 93)
			return 24;

		if (hunterLevel >= 85)
			return 22;

		if (hunterLevel >= 77)
			return 20;

		if (hunterLevel >= 69)
			return 18;

		return MIN_CAPACITY;
	}

	/**
	 * Exact game-object ids of the goat pit, the object the overlay draws its footprint on. Confirmed
	 * in a developer-mode session (see {@code docs/discovery.md}): the pit renders as game object
	 * {@code 62343} (id {@code 19750} is the ground object beneath it, which the tracker does not use).
	 * Name matching via {@link #PIT_NAME_FRAGMENT} still runs as a fallback if this set is emptied.
	 */
	static final Set<Integer> PIT_OBJECT_IDS =
		Collections.unmodifiableSet(new HashSet<>(Arrays.asList(62343)));

	/**
	 * Lower-cased fragment matched against {@link net.runelite.api.ObjectComposition#getName()} when
	 * {@link #PIT_OBJECT_IDS} is empty.
	 */
	static final String PIT_NAME_FRAGMENT = "goat pit";

	/**
	 * Lower-cased fragment matched against {@link net.runelite.api.NPC#getName()} when counting goats
	 * inside the pit footprint, used only if the pit exposes no varbit.
	 */
	static final String GOAT_NAME_FRAGMENT = "goat";

	/**
	 * Exact game-object ids of the spike supply — the object the player restocks spikes from, outlined
	 * when a pit needs lining and the player carries none. The Wyrmscraig goat-hunting plugin uses object
	 * id {@code 62349}; confirm in a developer-mode session (see {@code docs/discovery.md}). Name matching
	 * via {@link #SPIKE_SUPPLY_NAME_FRAGMENT} still runs as a fallback if this set is emptied.
	 */
	static final Set<Integer> SPIKE_SUPPLY_OBJECT_IDS =
		Collections.unmodifiableSet(new HashSet<>(Arrays.asList(62349)));

	/**
	 * Lower-cased fragment matched against {@link net.runelite.api.ObjectComposition#getName()} to
	 * identify the spike supply object when {@link #SPIKE_SUPPLY_OBJECT_IDS} is empty.
	 */
	static final String SPIKE_SUPPLY_NAME_FRAGMENT = "spike";

	/**
	 * Item id of the spikes the pit is lined with. Its presence in the inventory means the player can
	 * re-line a pit without a trip to the supply, so the supply highlight stays quiet. Observed as
	 * {@code 34016}; confirm in a developer-mode session (see {@code docs/discovery.md}).
	 */
	static final int SPIKES_ITEM_ID = 34016;

	/**
	 * Lower-cased menu action offered by an unspiked pit. Its presence on the pit's current
	 * composition is what marks the pit as needing spikes; a spiked pit does not offer it.
	 */
	static final String ADD_SPIKES_ACTION = "add spikes";

	/**
	 * Lower-cased menu action that empties a pit (the "Clear Goat Pit" / "Clear" option on the pit
	 * object). Matched on a pit entry so the swap can demote it off the left-click default while the pit
	 * is not yet full.
	 */
	static final String CLEAR_PIT_ACTION = "clear";

	/**
	 * Varbit holding the goat count. Object {@code 19750} carries no composition varbit, so the count
	 * lives in this player varbit (part of VarPlayer 5706) instead. Confirmed in a developer-mode
	 * session stepping 0 → 1 as a goat was caught; see {@code docs/discovery.md}. Set to {@code -1} to
	 * fall back to the object's declared varbit and then to NPC counting.
	 */
	static final int COUNT_VARBIT_OVERRIDE = 15725;

	/**
	 * Varbit holding the spikes state ({@code 0} = unspiked, {@code 1} = spiked), also part of
	 * VarPlayer 5706. Observed dropping to 0 when the pit was emptied and returning to 1 when spikes
	 * were re-added. Set to {@code -1} to fall back to detecting {@link #ADD_SPIKES_ACTION}.
	 */
	static final int SPIKES_VARBIT_OVERRIDE = 15724;

	/**
	 * Spot-anim (graphic) a goat carries while it is being lured toward the pit by a telegrab. Confirmed
	 * in-game: it appears on a goat the moment it is grabbed and clears when the goat lands.
	 */
	static final int IN_TRANSIT_SPOTANIM = 144;

	/**
	 * Animation a committed goat plays as it jumps into the pit, whether it was lured or prodded there.
	 * Confirmed in-game to follow {@link #IN_TRANSIT_SPOTANIM} on a lured goat and clear back to idle once
	 * it has fallen in. The goat is still committed to the pit during this phase, so it counts as in transit
	 * even though the flight spot-anim is already gone.
	 */
	static final int IN_TRANSIT_ANIM = 14463;

	/**
	 * Animation the local player plays when prodding a goat with a Cattleprod. Used to mark the goat the
	 * player is interacting with as prodded toward the pit, so it counts as in transit.
	 */
	static final int LOCAL_PROD_ANIM = 14450;

	private GoatIds()
	{
		throw new AssertionError("constants holder");
	}
}

