package com.oveduumnakal.goatindicators;

import java.time.Duration;
import java.time.Instant;
import javax.inject.Singleton;

/**
 * Tracks this catching session's running figures (#101): goats caught, Hunter XP gained, elapsed time, and
 * the per-hour rates derived from them.
 *
 * <p>The plugin feeds a fresh sample each game tick via {@link #update(Instant, int, long)}; the first
 * sample after a {@link #reset()} fixes the session baseline (the lifetime catch total and Hunter XP at that
 * moment), and every later sample reports the delta from it. The session clock starts later, at the first
 * catch or Hunter XP gain (#126), so time spent banking or walking to the pit does not dilute the rates. Rates
 * are the delta scaled by the time since that first gain.
 * Kept free of the client and the clock so it is unit-testable — the caller supplies "now" and the readings.
 *
 * <p>It also tallies the goat fur and horn collected this session (#102) from inventory changes fed through
 * {@link #recordInventory(int, int, boolean)}: every rise in the carried count while at the pit is a pickup.
 * The last carried counts survive a {@link #reset()}, so restarting the session never books the fur and horn
 * already in the inventory as fresh loot.
 */
@Singleton
class SessionStats
{
	/** Whether the first sample has fixed the catch and XP baseline. */
	private boolean baselined;

	/** Whether the first catch or XP gain has landed, which starts the session clock. */
	private boolean clockRunning;

	/** When the previous sample was taken, so an active sample can add the time since it. */
	private Instant last;

	private int startCatches;
	private long startXp;

	private Duration elapsed = Duration.ZERO;
	private int catches;
	private long xpGained;

	private int fur;
	private int horn;

	/** Fur and horn carried at the last inventory reading, or {@code -1} before the first one. */
	private int lastFurHeld = -1;
	private int lastHornHeld = -1;

	/**
	 * Records a fresh sample with the clock running; see {@link #update(Instant, int, long, boolean)}.
	 *
	 * @param now the current instant
	 * @param catchTotal the lifetime goats-caught total (its session delta is the catch count)
	 * @param hunterXp the current total Hunter experience
	 */
	void update(Instant now, int catchTotal, long hunterXp)
	{
		update(now, catchTotal, hunterXp, true);
	}

	/**
	 * Records a fresh sample. The first sample after construction or {@link #reset()} fixes the baseline;
	 * later samples report the catch and XP gained since. The clock starts at the first catch or XP gain and
	 * only accrues across samples taken while {@code active}, so the clock — and with it the per-hour rates —
	 * pauses while the player is away from the pit.
	 *
	 * @param now the current instant
	 * @param catchTotal the lifetime goats-caught total (its session delta is the catch count)
	 * @param hunterXp the current total Hunter experience
	 * @param active whether the player is at the pit, so the time since the previous sample counts
	 */
	void update(Instant now, int catchTotal, long hunterXp, boolean active)
	{
		if (!baselined)
		{
			baselined = true;
			startCatches = catchTotal;
			startXp = hunterXp;
		}
		else if (active && clockRunning)
		{
			elapsed = elapsed.plus(Duration.between(last, now));
		}

		last = now;
		catches = Math.max(0, catchTotal - startCatches);
		xpGained = Math.max(0, hunterXp - startXp);
		if (catches > 0 || xpGained > 0)
			clockRunning = true;
	}

	/**
	 * Re-anchors the catch baseline after the lifetime total is reset out from under the session, so the
	 * catches already counted this session survive rather than dropping to zero until the total climbs back.
	 *
	 * @param catchTotal the lifetime goats-caught total just after the reset
	 */
	void rebaseCatches(int catchTotal)
	{
		if (baselined)
			startCatches = catchTotal - catches;
	}

	/**
	 * Records the fur and horn now carried, booking any rise since the last reading as collected loot. Only
	 * rises seen while at the pit count, so withdrawing fur from a bank is not mistaken for a catch; the
	 * reading still updates the baseline either way. A drop (banking, grinding horns, dropping) books nothing,
	 * and the very first reading only fixes the baseline.
	 *
	 * @param furHeld goat fur now in the inventory
	 * @param hornHeld goat horns now in the inventory
	 * @param atPit whether a goat pit is loaded in the scene, so a rise came from looting it
	 */
	void recordInventory(int furHeld, int hornHeld, boolean atPit)
	{
		if (atPit && lastFurHeld >= 0)
		{
			fur += Math.max(0, furHeld - lastFurHeld);
			horn += Math.max(0, hornHeld - lastHornHeld);
		}

		lastFurHeld = furHeld;
		lastHornHeld = hornHeld;
	}

	/** Clears the session so the next {@link #update(Instant, int, long)} starts a fresh one. */
	void reset()
	{
		baselined = false;
		clockRunning = false;
		last = null;
		elapsed = Duration.ZERO;
		catches = 0;
		xpGained = 0;
		fur = 0;
		horn = 0;
	}

	/** @return whether a session is running (at least one sample has been recorded since the last reset). */
	boolean started()
	{
		return baselined;
	}

	/** @return the time elapsed since the session's first catch or XP gain, or zero before one. */
	Duration elapsed()
	{
		return elapsed;
	}

	/** @return goats caught this session. */
	int catches()
	{
		return catches;
	}

	/** @return Hunter experience gained this session. */
	long xpGained()
	{
		return xpGained;
	}

	/** @return goat fur collected this session. */
	int fur()
	{
		return fur;
	}

	/** @return goat horns collected this session. */
	int horn()
	{
		return horn;
	}

	/** @return goats caught per hour at the current rate, or 0 before any time has elapsed. */
	int catchesPerHour()
	{
		return (int) perHour(catches);
	}

	/** @return Hunter experience per hour at the current rate, or 0 before any time has elapsed. */
	long xpPerHour()
	{
		return perHour(xpGained);
	}

	/** @return {@code amount} scaled to an hourly rate over the elapsed time, or 0 when no time has elapsed. */
	private long perHour(long amount)
	{
		long seconds = elapsed.getSeconds();
		if (seconds <= 0)
			return 0;

		return amount * 3600L / seconds;
	}
}

